SELECT 'gongkao', '日常工作失误', 'kp-ms-emg-work', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "应急应变：日常工作失误"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "先补救，后担责。绝不推诿。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“你把一份重要文件发错群了，怎么办？” / “你统计的数据出错了，领导正在会上念，怎么办？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、答题骨架"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第一原则：立刻止损！发错群了马上撤回，撤回不了立刻在群里发声明请大家销毁并保密。领导会上念错了，马上递纸条或趁间隙小声提示领导更正。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第二原则：真诚认错。事后主动向领导检讨自己的粗心大意，绝不找借口（哪怕是因为别人催你）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第三原则：建章立制。痛定思痛，提出在以后的工作中建立“多人交叉复核机制”、“发送文件前的二次确认机制”来彻底杜绝。"}]}]}]}]}$$ AS jsonb), NULL, '日常工作失误的核心考点与高分作答技巧。', category_node.id, CAST('["面试", "应急应变", "工作失误"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_ms_emg_work", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
